    "id": "http://example.com/tickets/54321",
    "role": "childOf",
    "name": "Child ticket for Incident #12345",
    "relationshipType": {
      "@type": "TMF666:ParentChild",
      "@schemaLocation": "https://example.com/schemas/relationshipTypes.json#/ParentChild"
    }
  }
]
```

